using DataManagementSerialization = Microsoft.Dynamics.AX.Framework.Tools.DataManagement.Serialization;
using Microsoft.Dynamics.ApplicationFoundation.DIXF.Instrumentation;
using ServicesInstrumentation = Microsoft.Dynamics.ApplicationPlatform.Services.Instrumentation;

public class METDMFDefinitionGroupEntity extends common
{

}

Method.Source:
[SysODataActionAttribute("METDemoGetExecutionErrors", false)]
public static str METDemoGetExecutionErrors(DMFExecutionId executionId)
{
    #define.NewLine('\n')
    DMFStagingValidationLog stagingValidationLog;
    str logStr;
    SysInfoLogStr logText;
    FieldId execFieldId, defGroupFieldId;
    Common staging;
    DMFDefinitionGroupExecution execution;
    str errorJson;

    while select execution where execution.ExecutionId == executionId
    {
        DictTable      dictTable = new DictTable(tableName2Id(DMFEntity::find(execution.Entity).EntityTable));
        if (dictTable)
        {
            staging  = dictTable.makeRecord();
            execFieldId = fieldName2Id(staging.TableId,identifierStr(ExecutionId));
            defGroupFieldId = fieldName2Id(staging.TableId,identifierStr(DefinitionGroup));
            container keyFields = conPeek(DMFEntityBase::getPrimaryIndex(DictTable.name()),1);
            Notes dmfError;//vik

            Map errorMap = new Map(Types::String, Types::String);
            while select StagingColumnName,ErrorMessage, RecId,StagingRecId  from stagingValidationLog
                    order by stagingValidationLog.RecId  desc
                        where stagingValidationLog.ExecutionId == executionId
                            && stagingValidationLog.EntityName   == execution.Entity
                                join staging
                                    where staging.RecId == stagingValidationLog.StagingRecId
            {
                str keyText;
                str fieldidPrim;
                int counter,fieldIdloc;
                DictField dictTableloc;
                DictField dictFieldloc;

                DictFieldGroup dictFieldGrp = new DictFieldGroup(staging.tableId,METConstants::METReference);
                // If table is having table group METReference then check all the fields and assign those fields as custom dimensions
                if (dictFieldGrp)
                {
                    for (counter = 1; counter <= dictFieldGrp.numberOfFields(); counter++)
                    {
                        fieldIdloc = dictFieldGrp.field(counter);
                        dictFieldloc = new DictField(staging.tableId, fieldIdloc);

                        if (staging.(fieldIdloc))
                        {
                            dmfError = strFmt(METConstants::MultiStrfmtJson,dictFieldloc.label(),any2str(staging.(fieldIdloc)));
                        }
                    }
                }

                for (int i =1 ; i<= conLen(keyFields) ; i++)
                {
                    if (keyText)
                    {
                        keyText += ' ';
                    }
                    keyText += staging.(conPeek(keyFields,i));
                }
                str txt;
                str lookupKey = strFmt("{\"%1\":\"%2\",\"%3\":\"%4\",\"%5\,:\"%6\"",'RecordId',keyText,'Field',stagingValidationLog.StagingColumnName,'ErrorMessage',dmfError);
                lookupKey += "\"%1\"}";

                if (errorMap.exists(lookupKey))
                {
                    txt = errorMap.lookup(lookupKey);
                }
                logStr = #NewLine + strReplace(stagingValidationLog.ErrorMessage,'Results.','');
                txt += logStr;
                errorMap.insert(lookupKey,txt);
            }

            //Staging errors for columns
            DMFStagingExecutionErrors stagingErrors ;
            DMFStagingErrorCode dmfStagingErrorCode;
            int rowId = 0;
            while select stagingErrors where stagingErrors.ExecutionId == executionId
                outer join LabelId from dmfStagingErrorCode
                where dmfStagingErrorCode.ErrorCode == stagingErrors.ErrorCode
            {
                str lookupKey = strFmt("{\"%1\":\"%2\",\"%3\":\"%4\",\"%5\":",'RecordId',int2Str(rowId),'Field',stagingErrors.ErrorColumn,'ErrorMessage');
                lookupKey += "\"%1\"}";
                str errorTxt;
                if(dmfStagingErrorCode.LabelId)
                {
                    errorTxt = SysLabel::labelId2String(dmfStagingErrorCode.LabelId);
                    if(!errorTxt)
                        errorTxt = dmfStagingErrorCode.LabelId;
                }
                else
                {
                    errorTxt = stagingErrors.ErrorCode;
                }
                errorMap.insert(lookupKey,errorTxt);
                rowId++;
            }

            MapEnumerator enumerator = new MapEnumerator(errorMap);
            while (Enumerator.moveNext())
            {
                if (errorJson)
                {
                    errorJson += ',';
                }
                errorJson += strFmt(enumerator.currentKey(),Enumerator.currentValue());
            }
        }
        else
        {
            TelemetryRuntime::Warning('CompositeEntityDoNotContainStagingTable')
                .ClassName(tableStr(METDMFDefinitionGroupEntity))
                .MethodName(tableStaticMethodStr(METDMFDefinitionGroupEntity, METDemoGetExecutionErrors))
                .ExecutionId(executionId)
                .EntityName(execution.Entity)
                .Save();
        }
    }
    return strFmt('[%1]',errorJson);
}
